export default function (pi) {
  let dumps = 0;
  pi.registerTool({
    name: "dump", label: "Dump", description: "Oversized local output",
    parameters: { type: "object", properties: {} },
    async execute() {
      const sizes = [600000, 350000];
      const chars = sizes[Math.min(dumps++, sizes.length - 1)];
      return { content: [{ type: "text", text: `DUMP_HEAD ${"x".repeat(chars)} DUMP_TAIL` }, ...[]], details: {}, terminate: false };
    },
  });
}

export default function (pi) {
  pi.on("turn_end", (event, ctx) => {
    const branch = ctx.sessionManager.getBranch();
    const boundaries = branch.filter((entry) => entry.type === "compaction" && entry.details?.posthorse === 1);
    if (boundaries.length !== 1 || !event.toolResults.some((result) => result.toolName === "dump")) return;
    const owner = branch.find((entry) => entry.type === "message" && entry.message.role === "user");
    if (typeof ctx.sessionManager.appendContextEdit !== "function") throw new Error("appendContextEdit is not available");
    ctx.sessionManager.appendContextEdit(owner.id, null);
  });
}
